func TestSnapshotUpgradeLibraries_PartitionByte(t *testing.T) {
	// Verify the upgrade library partition byte is distinct from trie partitions
	require.NotEqual(t, TriePartitionLedgerState, upgradeLibraryDBPartition)
	require.NotEqual(t, TriePartitionAccounts, upgradeLibraryDBPartition)
	require.NotEqual(t, TriePartitionChainID, upgradeLibraryDBPartition)
}

func TestSnapshotUpgradeLibraries_LargeYAML(t *testing.T) {
	// Test with large YAML content (simulates real library YAML)
	store := common.NewInMemoryKVStore()

	// Create a large YAML (100KB)
	largeYAML := bytes.Repeat([]byte("# This is a large YAML file\n"), 4000)
	require.NoError(t, WriteUpgradeLibrary(store, 0, largeYAML))

	// Verify it's stored correctly
	var collected []UpgradeLibraryEntry
	IterateUpgradeLibraries(store, func(slot uint32, yaml []byte) bool {
		collected = append(collected, UpgradeLibraryEntry{Slot: slot, LibraryYAML: yaml})
		return true
	})

	require.Len(t, collected, 1)
	require.True(t, bytes.Equal(largeYAML, collected[0].LibraryYAML))
}

func TestSnapshotUpgradeLibraries_TmpFileFilter(t *testing.T) {
	// Test that tmp files are properly identified
	tmpDir, err := os.MkdirTemp("", "snapshot_test_tmp")
	require.NoError(t, err)
	defer os.RemoveAll(tmpDir)

	// Test file name patterns
	normalFile := "00000001234567890abcdef.snapshot"
	tmpFile := TmpSnapshotFileNamePrefix + normalFile

	require.True(t, len(tmpFile) > len(normalFile))
	require.True(t, tmpFile[:len(TmpSnapshotFileNamePrefix)] == TmpSnapshotFileNamePrefix)
	require.False(t, normalFile[:len(TmpSnapshotFileNamePrefix)] == TmpSnapshotFileNamePrefix)
}
